package glitch

import data.glitch_lib

# Define weak encryption algorithms and patterns
weak_algorithms := {"DES", "3DES", "ARC4", "RC4", "Blowfish", "IDEA", "MD5", "SHA1", "SHA-1", "ECB"}
weak_key_sizes := {"64", "56", "128", "1024"}
weak_protocols := {"SSLv3", "TLSv1.0", "TLSv1.1", "TLS1_0", "TLS1_1"}
weak_curves := {"secp192k1", "prime192v1", "secp192r1"}

# Check if a string value contains weak encryption patterns
check_weak_algorithm(value) {
    value.ir_type == "String"
    algorithm := upper(value.value)
    weak_algorithms[_] == algorithm
}

check_weak_algorithm(value) {
    value.ir_type == "String"
    algorithm := upper(value.value)
    contains(algorithm, "DES")
    not contains(algorithm, "AES")
}

check_weak_key_size(value) {
    value.ir_type == "String"
    size := value.value
    weak_key_sizes[_] == size
}

check_weak_key_size(value) {
    value.ir_type == "Integer"
    size := sprintf("%d", [value.value])
    weak_key_sizes[_] == size
}

check_weak_protocol(value) {
    value.ir_type == "String"
    protocol := upper(value.value)
    weak_protocols[_] == protocol
}

check_weak_curve(value) {
    value.ir_type == "String"
    curve := lower(value.value)
    weak_curves[_] == curve
}

# Check for disabled encryption
check_disabled_encryption(value) {
    value.ir_type == "Boolean"
    value.value == false
}

# Main detection rule for weak encryption algorithms
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check algorithm attributes
    attr.name in {"algorithm", "encryption_algorithm", "sse_algorithm", "cipher", "encryption"}
    check_weak_algorithm(attr.value)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Use of weak or deprecated cryptographic algorithm. (CWE-326)"
    }
}

# Detection rule for weak key sizes
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check key size attributes
    attr.name in {"key_length", "key_size", "bits", "rsa_key_bits", "key_bits"}
    check_weak_key_size(attr.value)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Use of weak key size for encryption. (CWE-326)"
    }
}

# Detection rule for weak TLS protocols
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check protocol and SSL policy attributes
    attr.name in {"min_tls_version", "ssl_policy", "protocols", "protocol"}
    check_weak_protocol(attr.value)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Use of weak TLS/SSL protocol version. (CWE-326)"
    }
}

# Detection rule for weak elliptic curves
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check curve attributes
    attr.name in {"curve", "ecdsa_curve"}
    check_weak_curve(attr.value)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Use of weak elliptic curve for encryption. (CWE-326)"
    }
}

# Detection rule for disabled encryption
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check encryption enabled flags
    attr.name in {"encryption_enabled", "enable_encryption", "storage_encrypted", "encrypted"}
    check_disabled_encryption(attr.value)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Encryption is disabled. (CWE-326)"
    }
}

# Detection rule for hardcoded IVs or salts
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check IV and salt attributes for hardcoded values
    attr.name in {"iv", "salt", "initialization_vector"}
    attr.value.ir_type == "String"
    count(attr.value.value) > 0
    not startswith(attr.value.value, "${")

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Hardcoded IV or salt value. (CWE-326)"
    }
}

