package glitch

import data.glitch_lib

# Define weak encryption algorithms, modes, and protocols
weak_algorithms := {"DES", "3DES", "RC4", "ARC4", "BLOWFISH", "IDEA", "MD5", "SHA1", "SHA-1", "MD5_CRYPT"}
weak_cipher_suites := {"TLS_RSA_WITH_AES_128_", "TLS_DHE_RSA_WITH_AES_128_", "SSL_", "TLS_1_0", "TLS_1_1"}
weak_key_sizes := {"64", "56", "128", "1024"}

# Helper to check for weak patterns in string values
contains_weak_pattern(value, patterns) {
    value.ir_type == "String"
    val := upper(value.value)
    some pattern
    patterns[pattern]
    regex.match(sprintf(".*%s.*", [pattern]), val)
}

# Helper to check integer key sizes
is_weak_key_size(value) {
    value.ir_type == "Integer"
    value.value == 64
} else {
    value.ir_type == "Integer"
    value.value == 56
} else {
    value.ir_type == "Integer"
    value.value == 128
} else {
    value.ir_type == "Integer"
    value.value == 1024
}

# Rule 1: Detect weak algorithms in attributes/variables
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    nodes := glitch_lib.all_attributes(parent)
    node := nodes[_]

    contains_weak_pattern(node.value, weak_algorithms)

    result := {
        "type": "sec_weak_crypt",
        "element": node,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Use of weak or deprecated cryptographic algorithm. (CWE-326)"
    }
}

# Rule 2: Detect weak key sizes in attributes/variables
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    nodes := glitch_lib.all_attributes(parent)
    node := nodes[_]

    is_weak_key_size(node.value)

    result := {
        "type": "sec_weak_crypt",
        "element": node,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Use of weak key size for encryption. (CWE-326)"
    }
}

# Rule 3: Detect weak cipher suites/protocols in string values
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    nodes := glitch_lib.all_attributes(parent)
    node := nodes[_]

    contains_weak_pattern(node.value, weak_cipher_suites)

    result := {
        "type": "sec_weak_crypt",
        "element": node,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Use of weak cipher suite or protocol. (CWE-326)"
    }
}

# Rule 4: Detect disabled encryption
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    nodes := glitch_lib.all_attributes(parent)
    node := nodes[_]

    node.value.ir_type == "Boolean"
    node.value.value == false
    name := lower(node.name)
    contains(name, "encrypt")

    result := {
        "type": "sec_weak_crypt",
        "element": node,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Encryption is disabled. (CWE-326)"
    }
}

# Rule 5: Detect weak encryption in variables (Ansible vars_prompt)
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    nodes := glitch_lib.all_variables(parent)
    node := nodes[_]

    contains_weak_pattern(node.value, weak_algorithms)

    result := {
        "type": "sec_weak_crypt",
        "element": node,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Use of weak encryption in variable. (CWE-326)"
    }
}

# Rule 6: Detect weak encryption in hash values (e.g., Ansible vars_prompt encrypt field)
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    attrs := glitch_lib.all_attributes(parent)
    attr := attrs[_]
    attr.value.ir_type == "Array"

    walk(attr.value.value, [path, element])
    element.ir_type == "Hash"

    some pair
    element.value[pair]
    pair.key.ir_type == "String"
    pair.value.ir_type == "String"

    pair.key.value == "encrypt"
    contains_weak_pattern(pair.value, weak_algorithms)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Use of weak encryption in configuration. (CWE-326)"
    }
}

